import os, glob, re

def load_grids():
    """Load all demo pairs and test input from session log"""
    session_dir = os.environ.get('RLM_SESSION_DIR', '')
    log_file = session_dir + '/../../sessions/' + os.path.basename(session_dir) + '.jsonl'

    G = {}
    with open(log_file) as f:
        content = f.read().replace('\\n', '\n')

    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n', content):
        k, h, w = m[1], int(m[2]), int(m[3])
        rows = content[m.end():].split('\n')[:h]
        if k not in G:
            rows_valid = []
            valid = True
            for r in rows:
                if r.strip():
                    parts = r.split()
                    if all(x.isdigit() for x in parts) and len(parts) == w:
                        rows_valid.append([int(x) for x in parts])
                    else:
                        valid = False
                        break
            if valid:
                G[k] = rows_valid

    return G

G = load_grids()
print("Loaded grids:", sorted(G.keys()))

# Print the test input
if 'Test input' in G:
    print("\n=== Test Input ===")
    for row in G['Test input']:
        print(' '.join(str(x) for x in row))

